from itertools import product

# Generate all possible binary sequences of length 24
sequences = list(product([-1, 1], repeat=24))

# Filter sequences based on the given constraints
valid_sequences = []
for seq in sequences:
    if seq[9] == -1 and seq[14] == 1 and seq[15] == -1 and seq[22] == -1:
        c = [0] * 24
        for k in range(1, 24):
            c_k = sum(seq[i] * seq[i + k] for i in range(24 - k))
            c[k - 1] = c_k
        if c[3] == 0 and c[9] == -2 and c[14] == -1 and c[19] == 0:
            valid_sequences.append(seq)

# Check if any valid sequence has low aperiodic autocorrelation
solutions = []
for seq in valid_sequences:
    c = [0] * 24
    for k in range(1, 24):
        c_k = sum(seq[i] * seq[i + k] for i in range(24 - k))
        c[k - 1] = c_k
    if sum(c_k ** 2 for c_k in c) <= 62:
        solutions.append(seq)

if solutions:
    print(solutions[0])
else:
    print("UNSATISFIABLE")
